names = sys.argv[1:] or list(P)
for name in names:
    path = "q_" + name + ".cpp"
    open(path, "w", newline="\n").write(PRE + P[name] + "\n")
    r = subprocess.run([B, "-program", name, path, "-quiet"], capture_output=True, text=True, errors="replace")
    out = (r.stdout + r.stderr).strip().split("\n")
    errs = [l for l in out if l.strip() and "build failed" not in l and "build succeeded" not in l]
    print("ok  " if r.returncode == 0 else "FAIL", name.ljust(30), (errs[0][:150] if errs else ""))
    for e in errs[1:2]:
        print(" " * 36 + e[:150])
